import pandas as pd
from sklearn.feature_extraction.text import TfidfVectorizer
import joblib

print("Loading data and beginning preprocessing pipeline...")

#collecting data from csv generated by data_collector.py
df = pd.read_csv("wikipedia_dataset.csv")

#function for cleaning text data
def clean_text(text):
    if not isinstance(text, str):
        return ""
    # Convert to lowercase
    text = text.lower()
    # Remove punctuation and special characters
    punctuation = [".", ",", "!", "?", ";", ":", "-", "_", "(", ")", "[", "]", "{", "}", "'", '"', "/", "\\", "@", "#", "$", "%", "^", "&", "*", "+", "=", "<", ">", "|"]
    for char in punctuation:
        text = text.replace(char, "")
    return text

# Apply the cleaning function to the 'text' column
df['cleaned_text'] = df['text'].apply(clean_text)

print("\nText cleaning complete. Sample of cleaned data:")
print(df[['category', 'cleaned_text']].head(2))

#Vectorizing the cleaned text data using TF-IDF
vectorizer = TfidfVectorizer(stop_words='english')

# Tranforms processed text into matrix
X = vectorizer.fit_transform(df['cleaned_text'])

# Target Labels for classification
Y = df['category']

print("\nMatrix shape (Rows of data, unique vocabulary terms): " + X.shape.__str__())

# Save the vectorizer for later use
joblib.dump(X, "X_matrix.pkl")
joblib.dump(Y, "Y_labels.pkl")
joblib.dump(vectorizer, "tfidf_vectorizer.pkl")
print("\nPreprocessing complete. Matrix and labels saved to 'X_matrix.pkl', 'Y_labels.pkl', and vectorizer saved to 'tfidf_vectorizer.pkl' have been saved to disk.")